"""Shared pytest fixtures.

Every test run uses a temporary data directory, never the project's data/
folder. The override must be set before app.py is imported because DATA,
UPLOADS and DB are resolved at import time.
"""

import os
import sys
import tempfile
from pathlib import Path

import pytest

# Keep the project tree free of test-generated bytecode.
sys.dont_write_bytecode = True

PROJECT_ROOT = Path(__file__).resolve().parents[1]
WORKBOOK = PROJECT_ROOT / "data" / "projects Upated9-11 (1).xlsx"

TEST_DATA_DIR = Path(tempfile.mkdtemp(prefix="broker_portal_test_data_"))
os.environ["BROKER_PORTAL_DATA"] = str(TEST_DATA_DIR)
os.environ.setdefault("BROKER_PORTAL_SECRET", "test-only-secret-do-not-use-in-production")

if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))


@pytest.fixture(scope="session")
def portal():
    import app as portal_module

    portal_module.app.config.update(TESTING=True)
    portal_module.init_db()
    return portal_module


@pytest.fixture(scope="session")
def admin_user_id(portal):
    conn = portal.db()
    try:
        row = conn.execute(
            "SELECT id FROM users WHERE role='admin' ORDER BY id LIMIT 1"
        ).fetchone()
        assert row is not None, "init_db() did not create an admin user"
        conn.execute(
            "UPDATE users SET must_change_password=0 WHERE id=?", (row["id"],)
        )
        conn.commit()
        return row["id"]
    finally:
        conn.close()


@pytest.fixture()
def app_client(portal):
    return portal.app.test_client()


@pytest.fixture()
def admin_client(portal, admin_user_id):
    client = portal.app.test_client()
    with client.session_transaction() as sess:
        sess["user_id"] = admin_user_id
        sess["role"] = "admin"
        sess["email"] = "admin@local"
        sess["_csrf"] = "test-csrf-token"
    return client


@pytest.fixture(scope="session")
def imported_version(portal, admin_user_id):
    assert WORKBOOK.exists(), f"Bundled workbook is missing: {WORKBOOK}"
    conn = portal.db()
    try:
        cur = conn.execute(
            "INSERT INTO versions(filename,status,created_at,created_by) VALUES(?,?,?,?)",
            (WORKBOOK.name, "draft", "2026-01-01T00:00:00", admin_user_id),
        )
        version_id = cur.lastrowid
        conn.commit()
    finally:
        conn.close()

    portal.import_workbook(WORKBOOK, version_id)
    return version_id


@pytest.fixture(scope="session")
def live_version(portal, imported_version):
    conn = portal.db()
    try:
        conn.execute("UPDATE versions SET status='archived' WHERE status='live'")
        conn.execute("UPDATE versions SET status='live' WHERE id=?", (imported_version,))
        conn.commit()
    finally:
        conn.close()
    return imported_version


@pytest.fixture(scope="session")
def workbook_path():
    return WORKBOOK
